#!/usr/bin/env python3
from pathlib import Path
import re

src=Path('process/tmp_publish_bill_tracker_full_post_contacts.py')
text=src.read_text(encoding='utf-8')

# 1) Explainer slides: one shared body size across the four comparable panels.
old="""    panel(d,60,232,460,270,*a,body_size=23); panel(d,560,232,460,270,*b,body_size=23)\n    panel(d,60,526,460,286,*c,body_size=22); panel(d,560,526,460,286,*e,body_size=22)\n"""
new="""    # Use one shared body size across all four explainer panels. Find the\n    # largest size that fits the most constrained panel, then apply it to all.\n    panel_specs=[(60,232,460,270,a),(560,232,460,270,b),(60,526,460,286,c),(560,526,460,286,e)]\n    shared_size=30\n    while shared_size>=18:\n        fits=True\n        for _x,_y,_w,_h,_item in panel_specs:\n            _title,_body=_item\n            _f=font(shared_size)\n            _lines=wrap(d,_body,_f,_w-48)\n            _yy=_y+56\n            for _line in _lines:\n                _,_lh=measure(d,_line,_f); _yy += _lh+4\n            if len(_lines)>8 or _yy>_y+_h-18:\n                fits=False; break\n        if fits: break\n        shared_size-=1\n    for _x,_y,_w,_h,_item in panel_specs:\n        panel(d,_x,_y,_w,_h,*_item,body_size=shared_size)\n"""
if old not in text:
    raise RuntimeError('make_explainer panel block not found')
text=text.replace(old,new,1)

# 2) Pharmacy Bill: explain oral question / recorded division procedure instead of a fake tally.
pattern=r"def make_no_division\(path\):\n.*?\ndef make_glossary_terms\(path\):"
replacement="""def make_no_division(path):\n    im=slide(); d=ImageDraw.Draw(im)\n    centered(d,70,'Pharmacy Contraception · How This Passed',font(40,True),TEXT); d.rectangle([110,140,970,145],fill=ACCENT)\n    centered(d,178,'PASSED WITHOUT A RECORDED DIVISION',font(26,True),ACCENT)\n\n    steps=[\n      ('1 · QUESTION PUT','The Chair puts the question to the House. Members respond Tá or Níl aloud.'),\n      ('2 · RESULT DECLARED','The Chair judges the response and declares which side has carried the question.'),\n      ('3 · DIVISION IF REQUIRED','If the result is challenged and a formal division is taken, individual members’ votes are recorded. That is what produces the party tally used on our other slides.'),\n    ]\n    y=255\n    for title,body in steps:\n        d.rounded_rectangle([90,y,990,y+205],radius=22,fill=PANEL,outline=BORDER,width=2)\n        d.text((120,y+24),title,font=font(23,True),fill=ACCENT)\n        draw_wrapped(d,120,y+70,body,font(23),TEXT,840,gap=7,max_lines=5)\n        y+=230\n\n    d.rounded_rectangle([90,955,990,1185],radius=22,fill=PANEL2,outline=ACCENT,width=3)\n    centered(d,985,'WHAT HAPPENED HERE',font(23,True),ACCENT)\n    draw_centered_wrapped(d,1032,'This Bill passed its Dáil stage without a recorded division. The decision stood, but no member-by-member Tá / Níl tally was produced, so there is no party breakdown to show.',font(22),TEXT,820,gap=7,max_lines=6)\n    footer(d,'EirePolitic · Parliamentary procedure · No recorded division'); im.save(path)\n\ndef make_glossary_terms(path,current_stage='ENACTED'):"""
text,n=re.subn(pattern,replacement,text,flags=re.S)
if n!=1:
    raise RuntimeError(f'make_no_division replacement count={n}')

# 3) Replace glossary-terms implementation: reusable stage highlight + shared fitted body text.
pattern=r"def make_glossary_terms\(path,current_stage='ENACTED'\):\n.*?\ndef make_glossary_votes\(path\):"
replacement="""def make_glossary_terms(path,current_stage='ENACTED'):\n    im=slide(); d=ImageDraw.Draw(im)\n    centered(d,66,'GLOSSARY',font(48,True),TEXT)\n    centered(d,128,'HOW A BILL MOVES THROUGH PARLIAMENT',font(22,True),ACCENT)\n    d.rectangle([150,174,930,179],fill=ACCENT)\n\n    # Reusable stage strip. The current post's stage/status is highlighted.\n    stages=['FIRST','SECOND','COMMITTEE','REPORT','FINAL','OTHER HOUSE','PRESIDENT','ENACTED']\n    active=str(current_stage).upper()\n    x0,y0,bw,gap=48,218,108,18\n    for i,label in enumerate(stages):\n        x=x0+i*(bw+gap)\n        is_active=(label==active)\n        fill=ACCENT if is_active else PANEL\n        outline=ACCENT if is_active else BORDER\n        txt=BG if is_active else ACCENT\n        d.rounded_rectangle([x,y0,x+bw,y0+104],radius=14,fill=fill,outline=outline,width=3 if is_active else 2)\n        d.text((x+bw/2,y0+27),str(i+1),font=font(15,True),fill=txt,anchor='mm')\n        lines=wrap(d,label,font(13,True),bw-14)\n        d.multiline_text((x+bw/2,y0+70),'\\n'.join(lines),font=font(13,True),fill=txt,anchor='mm',align='center',spacing=2)\n        if i<len(stages)-1:\n            d.polygon([(x+bw+5,y0+52),(x+bw+13,y0+46),(x+bw+13,y0+58)],fill=ACCENT)\n\n    centered(d,342,f'THIS POST: {active}',font(18,True),ACCENT)\n    draw_centered_wrapped(d,375,'A Government Bill normally moves through stages in one House, then through the other House. Once both Houses agree the text and the President signs it, the Bill becomes law.',font(20),TEXT,900,gap=6,max_lines=4)\n    centered(d,466,'COMMON TERMS',font(22,True),ACCENT)\n\n    defs=[\n      ('BILL','A proposed law.'),\n      ('DÁIL ÉIREANN','Ireland’s directly elected house; members are TDs.'),\n      ('SEANAD ÉIREANN','Ireland’s second parliamentary chamber; members are Senators.'),\n      ('STAGE','A formal step in considering, amending or approving a Bill.'),\n      ('ENACTED','The Bill has completed the required process and become law.'),\n    ]\n    boxes=[(80,510,520,675),(560,510,1000,675),(80,700,520,865),(560,700,1000,865),(300,890,780,1055)]\n\n    # One shared body size for all five definition boxes. The longest/most\n    # constrained definition determines the size; every box then uses it.\n    shared=30\n    while shared>=17:\n        ok=True\n        for (_term,body),(x1,y1,x2,y2) in zip(defs,boxes):\n            f=font(shared)\n            lines=wrap(d,body,f,x2-x1-42)\n            heights=[measure(d,line,f)[1] for line in lines]\n            needed=sum(heights)+max(0,len(lines)-1)*5\n            available=(y2-y1)-76\n            if len(lines)>4 or needed>available:\n                ok=False; break\n        if ok: break\n        shared-=1\n\n    for (term,body),(x1,y1,x2,y2) in zip(defs,boxes):\n        d.rounded_rectangle([x1,y1,x2,y2],radius=18,fill=PANEL,outline=BORDER,width=2)\n        cx=(x1+x2)/2\n        tw,_=measure(d,term,font(20,True)); d.text((cx-tw/2,y1+20),term,font=font(20,True),fill=ACCENT)\n        f=font(shared)\n        lines=wrap(d,body,f,x2-x1-42)\n        block='\\n'.join(lines)\n        d.multiline_text((cx,y1+104),block,font=f,fill=TEXT,anchor='mm',align='center',spacing=5)\n\n    footer(d,'EirePolitic · Glossary · Parliamentary process & terms')\n    im.save(path)\n\ndef make_glossary_votes(path):"""
text,n=re.subn(pattern,replacement,text,flags=re.S)
if n!=1:
    raise RuntimeError(f'glossary terms replacement count={n}')

# 4) Replace vote-glossary implementation: one shared fitted body size across comparable cards.
pattern=r"def make_glossary_votes\(path\):\n.*?\ndef contact\(paths,out,title\):"
replacement="""def make_glossary_votes(path):\n    im=slide(); d=ImageDraw.Draw(im)\n    centered(d,95,'GLOSSARY',font(48,True),TEXT)\n    centered(d,157,'HOW TO READ THE VOTE SLIDES',font(22,True),ACCENT)\n    d.rectangle([150,205,930,210],fill=ACCENT)\n\n    cards=[\n      ('TÁ / NÍL','Tá means Yes. Níl means No. What “Yes” or “No” means depends on the exact proposition being voted on.',175),\n      ('DIVISION','A recorded vote where individual members’ votes are listed.',150),\n      ('AMENDMENT','A proposed change. A Tá on an amendment supports that change. It does not automatically mean support for the whole Bill.',200),\n      ('NO RECORDED VOTE','No vote is recorded for that TD in the division data. It does not automatically mean the TD was absent.',185),\n    ]\n\n    # Fit once using the most constrained card, then use that exact body size\n    # across all four definitions.\n    shared=30\n    while shared>=18:\n        ok=True\n        for _t,body,h in cards:\n            f=font(shared)\n            lines=wrap(d,body,f,812)\n            needed=sum(measure(d,line,f)[1] for line in lines)+max(0,len(lines)-1)*4\n            if len(lines)>6 or needed>h-78:\n                ok=False; break\n        if ok: break\n        shared-=1\n\n    y=270\n    for t,b,h in cards:\n        panel(d,110,y,860,h,t,b,head_size=24,body_size=shared,max_lines=6)\n        y+=h+20\n\n    d.rounded_rectangle([110,1055,970,1208],radius=20,fill=PANEL2,outline=ACCENT,width=3)\n    centered(d,1080,'OUR VOTE-LABEL RULE',font(22,True),ACCENT)\n    # This is a different component, so it has its own size but is also fitted\n    # to make better use of the available panel.\n    safeguard='We describe the exact proposition shown. Speaking about a Bill does not equal supporting it, and a linked vote may be about an amendment or procedure rather than the Bill itself.'\n    sf=24\n    while sf>=18:\n        f=font(sf); lines=wrap(d,safeguard,f,790)\n        needed=sum(measure(d,line,f)[1] for line in lines)+max(0,len(lines)-1)*5\n        if len(lines)<=4 and needed<=68: break\n        sf-=1\n    draw_centered_wrapped(d,1120,safeguard,font(sf),TEXT,790,gap=5,max_lines=4)\n    footer(d,'EirePolitic · Glossary · Vote terms & safeguards')\n    im.save(path)\n\ndef contact(paths,out,title):"""
text,n=re.subn(pattern,replacement,text,flags=re.S)
if n!=1:
    raise RuntimeError(f'glossary votes replacement count={n}')

# Explicitly pass the reusable current-stage value for these enacted posts.
text=text.replace("make_glossary_terms(OUT/'post1_07_glossary_terms.png')", "make_glossary_terms(OUT/'post1_07_glossary_terms.png',current_stage='ENACTED')")
text=text.replace("make_glossary_terms(OUT/'post2_07_glossary_terms.png')", "make_glossary_terms(OUT/'post2_07_glossary_terms.png',current_stage='ENACTED')")

Path('process/tmp_publish_bill_tracker_full_post_contacts_patched.py').write_text(text,encoding='utf-8')
print('patched renderer written')
